            expect(res.status).toHaveBeenCalledWith(200);
            expect(res.json).toHaveBeenCalledWith({
                message: "OAuth authentication successful",
                token: 'app_access_jwt',
                refreshToken: 'app_refresh_jwt',
                user: { id: 'usr_123', role: 'USER' }
